-- VSSD Student Help Desk database. Run all of this in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default 'Student',course text not null default 'BCA',role text not null default 'student' check(role in('student','admin')),created_at timestamptz not null default now());
create table if not exists public.tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,request_type text not null,course text not null default 'Other',subject text not null check(char_length(subject) between 1 and 120),details text not null check(char_length(details) between 1 and 3000),status text not null default 'Submitted' check(status in('Submitted','In review','Resolved','Closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.lost_found(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in('Lost','Found')),title text not null check(char_length(title) between 1 and 100),place_time text,description text not null check(char_length(description) between 1 and 1500),status text not null default 'Open' check(status in('Open','Matched','Returned','Closed')),created_at timestamptz not null default now());
create table if not exists public.event_registrations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,event_name text not null check(char_length(event_name) between 1 and 140),course text not null default 'Other',message text,status text not null default 'Registered' check(status in('Registered','Reviewed','Accepted','Waitlisted','Cancelled')),created_at timestamptz not null default now());
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 160),category text not null default 'General',body text not null check(char_length(body) between 1 and 4000),link text,published boolean not null default false,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.resources(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 160),course text not null default 'All courses',resource_type text not null default 'Other' check(resource_type in('Notes','Syllabus','Lecture','Other')),unit text,description text,url text not null,published boolean not null default false,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
-- A profile is automatically created on signup. Users can never set their own role.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,course,role) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'full_name',''),'Student'),coalesce(nullif(new.raw_user_meta_data->>'course',''),'BCA'),'student') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_helpdesk_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'); $$;
alter table public.profiles enable row level security; alter table public.tickets enable row level security; alter table public.lost_found enable row level security; alter table public.event_registrations enable row level security; alter table public.announcements enable row level security; alter table public.resources enable row level security;
drop policy if exists profile_read on public.profiles; create policy profile_read on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_helpdesk_admin());
drop policy if exists profile_update on public.profiles; create policy profile_update on public.profiles for update to authenticated using(id=(select auth.uid()) or public.is_helpdesk_admin()) with check((id=(select auth.uid()) and role='student') or public.is_helpdesk_admin());
drop policy if exists ticket_read on public.tickets; create policy ticket_read on public.tickets for select to authenticated using(user_id=(select auth.uid()) or public.is_helpdesk_admin()); drop policy if exists ticket_insert on public.tickets; create policy ticket_insert on public.tickets for insert to authenticated with check(user_id=(select auth.uid())); drop policy if exists ticket_update on public.tickets; create policy ticket_update on public.tickets for update to authenticated using(public.is_helpdesk_admin()) with check(public.is_helpdesk_admin());
drop policy if exists lost_read on public.lost_found; create policy lost_read on public.lost_found for select to authenticated using(user_id=(select auth.uid()) or public.is_helpdesk_admin()); drop policy if exists lost_insert on public.lost_found; create policy lost_insert on public.lost_found for insert to authenticated with check(user_id=(select auth.uid())); drop policy if exists lost_update on public.lost_found; create policy lost_update on public.lost_found for update to authenticated using(public.is_helpdesk_admin()) with check(public.is_helpdesk_admin());
drop policy if exists event_read on public.event_registrations; create policy event_read on public.event_registrations for select to authenticated using(user_id=(select auth.uid()) or public.is_helpdesk_admin()); drop policy if exists event_insert on public.event_registrations; create policy event_insert on public.event_registrations for insert to authenticated with check(user_id=(select auth.uid())); drop policy if exists event_update on public.event_registrations; create policy event_update on public.event_registrations for update to authenticated using(public.is_helpdesk_admin()) with check(public.is_helpdesk_admin());
drop policy if exists announcement_read on public.announcements; create policy announcement_read on public.announcements for select to anon,authenticated using(published=true or public.is_helpdesk_admin()); drop policy if exists announcement_insert on public.announcements; create policy announcement_insert on public.announcements for insert to authenticated with check(public.is_helpdesk_admin() and created_by=(select auth.uid())); drop policy if exists announcement_update on public.announcements; create policy announcement_update on public.announcements for update to authenticated using(public.is_helpdesk_admin()) with check(public.is_helpdesk_admin()); drop policy if exists announcement_delete on public.announcements; create policy announcement_delete on public.announcements for delete to authenticated using(public.is_helpdesk_admin());
drop policy if exists resource_read on public.resources; create policy resource_read on public.resources for select to anon,authenticated using(published=true or public.is_helpdesk_admin()); drop policy if exists resource_insert on public.resources; create policy resource_insert on public.resources for insert to authenticated with check(public.is_helpdesk_admin() and created_by=(select auth.uid())); drop policy if exists resource_update on public.resources; create policy resource_update on public.resources for update to authenticated using(public.is_helpdesk_admin()) with check(public.is_helpdesk_admin()); drop policy if exists resource_delete on public.resources; create policy resource_delete on public.resources for delete to authenticated using(public.is_helpdesk_admin());
grant usage on schema public to anon,authenticated; grant select on public.announcements,public.resources to anon,authenticated; grant select,update on public.profiles to authenticated; grant select,insert,update on public.tickets,public.lost_found,public.event_registrations to authenticated; grant insert,select,update,delete on public.announcements,public.resources to authenticated;
-- After registering your account, run this in SQL Editor with your own email to grant admin:
-- update public.profiles p set role='admin' from auth.users u where p.id=u.id and u.email='YOUR-EMAIL@example.com';
